const DEFAULT_NAME_PREFIXES = [
  ['Import SQL file', 'workspace.task.name.importSql'],
  ['Import table data', 'workspace.task.name.importTable'],
  ['Export table data', 'workspace.task.name.exportTable'],
] as const;

const WIZARD_IMPORT_NAME = /^Import (.+)$/;

export type TaskNameMessageKey =
  | 'workspace.task.name.importSql'
  | 'workspace.task.name.importTable'
  | 'workspace.task.name.exportTable'
  | 'workspace.task.name.importTarget';

type Translate = (key: TaskNameMessageKey, ...args: Array<string | number>) => string;

/**
 * Localizes the default task names generated by the backend. A name the user provided (or a
 * format this helper does not know) is shown unchanged.
 */
export const formatTaskName = (name: string, translate: Translate) => {
  for (const [prefix, key] of DEFAULT_NAME_PREFIXES) {
    if (name === prefix) {
      return translate(key);
    }
    if (name.startsWith(`${prefix} - `)) {
      return `${translate(key)}${name.slice(prefix.length)}`;
    }
  }
  const wizardImport = WIZARD_IMPORT_NAME.exec(name);
  return wizardImport ? translate('workspace.task.name.importTarget', wizardImport[1]) : name;
};
